}

Method.Source:
/// <summary>
/// Method wrapper for invoking the method that sets defaults on the main data source.
/// method is necessary since existing forms cannot add implementations in extensions
/// </summary>
public void callerDS_initValue()
{
    next callerDS_initValue();
    FormRun avaCaller_dsFormRun = caller_ds.formRun();
    FormRun avaCaller = avaCaller_dsFormRun.args().caller();        // needed to get the caller of the form DirPartyQuickCreateForm, which calls this class

    if (!dirPartyFormCaller)
    {
        switch(avaCaller.name())
        {
            case formStr(SalesTable):
            case formStr(AVAKBVRequestTable):
                avaCaller.quickCreate_DirPartyEntity_InitValue(caller_ds);
                caller_ds.rereadReferenceDataSources();
                break;
            case formStr(smmBusRelTable) :
                if (avaCaller_dsFormRun.args().menuItemName() ==  menuItemDisplayStr(AVAsmmBusRelQuickCopy))
                {
                    smmBusRelTable      copySmmBusRelTable = avaCaller_dsFormRun.args().record();
                    if (copySmmBusRelTable)
                    {
                        if(caller_ds.table() == tableNum(smmBusRelTable))
                        {
                            smmBusRelTable curCreatedSmmBusRelTable = caller_ds.cursor();
                            curCreatedSmmBusRelTable.DlvMode = copySmmBusRelTable.DlvMode;
                            curCreatedSmmBusRelTable.Segment = copySmmBusRelTable.Segment;
                            curCreatedSmmBusRelTable.Subsegment = copySmmBusRelTable.Subsegment;
                            curCreatedSmmBusRelTable.KCS_QuotationEnabled = copySmmBusRelTable.KCS_QuotationEnabled;
                            curCreatedSmmBusRelTable.KCS_RequestEnabled   = copySmmBusRelTable.KCS_RequestEnabled;
                        }
                    }
                }
                break;

            default:
                break;

        }
    }
}
